  "summary": "The codebase contains 5 identified issues ranging from critical XSS vulnerabilities to maintainability concerns. The most critical finding is the reflected XSS vulnerability in the /hello endpoint. Overall code health is poor due to lack of modularity, missing security headers, and hardcoded configurations.",
  "fixed_code": "/**\n * Express server providing greeting and status endpoints.\n */\nconst express = require(\"express\");\nconst helmet = require(\"helmet\");\nconst escape = require(\"escape-html\");\n\nconst app = express();\napp.use(helmet());\n\napp.get(\"/hello\", (req, res) => {\n    const name = typeof req.query.name === 'string' ? req.query.name : 'friend';\n    res.type(\"html\").send(`<main><h1>Hello, ${escape(name)}!</h1></main>`);\n});\n\napp.get(\"/status\", (req, res) => {\n    res.json({ ok: true });\n});\n\nconst PORT = process.env.PORT || 3000;\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
